<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>WarnAI · Workspace Intelligence</title><style>:root{--bg:#080d1a;--card:#121b2e;--line:#263653;--text:#edf2ff;--muted:#91a0bf;--accent:#76a8ff;--good:#7ee2ad}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% 0,#142445 0,#080d1a 46%);color:var(--text);font:15px Inter,system-ui,sans-serif}main{max-width:1180px;margin:auto;padding:36px 24px}.top{display:flex;justify-content:space-between;align-items:center}.logo{font-weight:800;letter-spacing:.14em;color:var(--accent)}.status{border:1px solid #295338;color:var(--good);border-radius:20px;padding:8px 14px;font-size:12px}.hero{padding:72px 0 38px;max-width:700px}.hero h1{font-size:clamp(42px,7vw,76px);line-height:.98;margin:12px 0}.muted{color:var(--muted);line-height:1.65}.layout{display:grid;grid-template-columns:1.35fr .65fr;gap:18px}.card{background:rgba(18,27,46,.9);border:1px solid var(--line);border-radius:18px;padding:22px;box-shadow:0 20px 60px #0002}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.metric{background:#0e1628;border-radius:12px;padding:16px}.metric span{color:var(--muted);font-size:12px}.metric b{font-size:25px;display:block;margin-top:7px}.drop{border:1px dashed #46618e;padding:24px;border-radius:12px;text-align:center;margin-top:15px}button{border:0;background:var(--accent);color:#071024;padding:12px 18px;border-radius:9px;font-weight:800;cursor:pointer}input[type=file]{max-width:100%;color:var(--muted)}.search{display:flex;gap:8px;margin-top:14px}.search input{flex:1;background:#0b1324;border:1px solid var(--line);border-radius:9px;padding:12px;color:var(--text)}.result{border-top:1px solid var(--line);padding:15px 0}.score{color:var(--good);font-size:12px}.toast{margin-top:12px;color:var(--good)}@media(max-width:800px){.layout{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,1fr)}} </style></head><body><main><header class="top"><div class="logo">WARNAI</div><div class="status" id="status">● CHECKING ENGINE</div></header><section class="hero"><div class="logo">PRIVATE WORKSPACE INTELLIGENCE</div><h1>Turn your repository into clear answers.</h1><p class="muted">Normalize source code, retrieve the right context with local NLP and semantic embeddings, and measure context efficiency from one focused workspace.</p></section><section class="metrics card"><div class="metric"><span>Documents</span><b id="docs">0</b></div><div class="metric"><span>Queries</span><b id="queries">0</b></div><div class="metric"><span>Tokens</span><b id="tokens">0</b></div><div class="metric"><span>Retrieval</span><b id="mode">—</b></div></section><section class="layout"><div class="card"><h2>Index workspace</h2><p class="muted">Upload a ZIP repository or a source file. Processing stays inside your deployment.</p><form id="upload" class="drop"><input id="file" type="file" accept=".zip,.py,.php,.js,.ts,.md,.json,.yaml,.yml" required><br><br><button>Normalize and index</button></form><div id="toast" class="toast"></div></div><div class="card"><h2>Search context</h2><p class="muted">Ask a natural language question and retrieve the most relevant normalized files.</p><form id="search" class="search"><input id="query" placeholder="Where is authentication handled?" required><button>Search</button></form><div id="results" class="muted" style="margin-top:18px">Your results will appear here.</div></div></section></main><script>const $=x=>document.getElementById(x);async function api(url,opt){let r=await fetch(url,opt);if(!r.ok)throw Error((await r.json()).message||'Request failed');return r.json()}async function refresh(){try{let h=await api('/api/health'),a=h.analytics||{};$('status').textContent='● ENGINE ONLINE';$('docs').textContent=a.documents||0;$('queries').textContent=a.queries||0;$('tokens').textContent=a.estimated_tokens||0;$('mode').textContent=a.deep_learning_embeddings?'HYBRID':'BM25'}catch(e){$('status').textContent='● ENGINE OFFLINE'}}$('upload').onsubmit=async e=>{e.preventDefault();let f=new FormData();f.append('file',$('file').files[0]);$('toast').textContent='Processing…';try{let r=await api('/api/normalize',{method:'POST',body:f});$('toast').textContent=`Indexed ${r.count} files in ${r.elapsed_ms} ms`;refresh()}catch(e){$('toast').textContent=e.message}};$('search').onsubmit=async e=>{e.preventDefault();try{let r=await api('/api/search',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({query:$('query').value,limit:8})});$('results').innerHTML=r.results.length?r.results.map(x=>`<div class="result"><b>${x.path}</b> <span class="score">score ${x.score}</span><p class="muted">${x.markdown.slice(0,220).replaceAll('<','&lt;')}…</p></div>`).join(''):'No relevant context found';refresh()}catch(e){$('results').textContent=e.message}};refresh()</script></body></html>
